sparql_response:
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?school ?countryLabel WHERE {
  VALUES ?school { dbr:The_Lawrence_International_School dbr:City_Montessori_School,_Aliganj_Branch }

  # Try direct country property (prefer dbp)
  OPTIONAL { ?school dbp:country ?country . }
  OPTIONAL { ?school dbo:country ?country . }

  # Fallback: get country via city
  OPTIONAL {
    ?school dbo:city ?city .
    ?city dbo:country ?country .
  }

  # Get English label of the country
  OPTIONAL {
    ?country rdfs:label ?countryLabel .
    FILTER (lang(?countryLabel) = "en")
  }
}
LIMIT 100

